  AwakerTalent_122607_TalentDesc_1 = {
    Text = "Ogni 2 carte \"Colpo\" giocate, Mouchette esegue una Caccia, infliggendo casualmente 1 istanza di DAN pari al 30% dell'ATT di Mouchette (conta come \"Colpo\"). Questo effetto può attivarsi fino a 4 volte per turno."
