  AwakerTalent_125362_TalentDesc_1 = {
    Text = "Questo talento è efficace solo negli stage \"Regno Astrale\".\nCOS, ATT e DIF di questo Risvegliatore +[Arg1]%, e ottiene [Arg2] Energia-S al primo Risveglio.\nL'effetto Attivazione Veleno di tutti i Risvegliatori +[Arg3]%. \nOgni stack di \"Ammaliato\" riduce inoltre il DAN inflitto dai nemici \"Umanoide\" dell'1%, e quando \"Ammaliato\" viene rimosso, ogni stack infligge Danno Fisso pari all'1% della Salute massima del bersaglio sui nemici \"Umanoide\"."
  },
