  AwakerTalent_127223_TalentDesc_1 = {
    Text = "Quando Arachne è nel team, il Reame Ultra si ritesse in Singolarità: Ultra.\nNavetta Dimensionale: Dopo aver giocato la prima Carta di comando ogni turno, una Copia Base Illusione di essa verrà inserita nell'Ultra Spazio e riceverà 25 accumuli di Faro di Singolarità. Questo non può attivarsi durante i Turni Ultra. Se una carta attiva la Navetta Dimensionale, beneficia anche degli effetti del Faro di Singolarità.\nFaro di Singolarità: Per ogni accumulo, il Danno Finale di una carta, il guadagno FOR e DAN Tentacolo Fisso, Veleno Fisso e Contrattacco Fisso aumentano ciascuno del +2%; Scudo Finale, Recupero PV e Riduzione del potere aumentano ciascuno del +1%. Questo effetto si azzera quando la carta viene giocata. Le carte con questo effetto non possono attivare la Navetta Dimensionale.\nUltra Spazio: Quando è pieno, iniziare il Turno Ultra non termina il turno né ne inizia uno nuovo; scarta tutte le carte non Conservate, risolvi i loro effetti Illusione, preleva tutte le carte dall'Ultra Spazio e imposta l'Arithmetica a 5. Il turno corrente continua come Turno Ultra.\nAnnientamento di Singolarità: Preleva la carta più a sinistra dall'Ultra Spazio e portala in mano. Tempo di recupero di 3 turni.\nAll'inizio dell'indagine, ottieni +50% di Amplificazione del Danno e 15 accumuli di Prisma di Singolarità.\nPrisma di Singolarità: Gli effetti di tutte le Carte di comando aumentano come se avessero questo numero di accumuli di Faro di Singolarità.\nUltra Padronanza: Per ogni punto di Padronanza del Reame, gli accumuli di Faro di Singolarità dal Prisma di Singolarità e dalla Navetta Dimensionale aumentano dello 0,05%.\nIperdimensione Pura: Se il team è composto solo da Risvegliatori Ultra o del Caos, l'effetto di Ultra Padronanza e l'Amplificazione del Danno del Reame sono raddoppiati."
  },
