  AwakerTalent_130398_TalentDesc_1 = {
    Text = "Questo talento è efficace solo nelle fasi del \"Regno Astrale\".\nCOS, ATT e DIF di questo Risvegliatore +[Arg1]%, e ottiene [Arg2] Keyflare al primo Risveglio.\nIl Risvegliatore selezionato dal \"Canto di Saya\" ottiene [Arg3] accumuli di \"Festa della Propagazione\" e fa sì che la prossima Posse sia attivata 2 volte.\nSaya infligge +[Arg4]% accumuli di Corrosione ai nemici \"Caro\"."
  },
