  AwakerTalent_130400_TalentDesc_1 = {
    Text = "·Questo Talento ha effetto solo nelle fasi \"Stellar Chapter\".\n·COS, ATT e Difesa di questo Risvegliatore aumentano del [Arg1]%, e dopo che questo Risvegliatore gioca Risveglio per la prima volta, ottiene [Arg2] Keyflare.\n·L'Effetto di Riduzione del potere e il moltiplicatore di potere ottenuto da \"Ombra della Landa Sconfinata\" aumentano del [Arg3]%. Ogni volta che ha effetto, il successivo \"Mirino Macchiato di Peccato\" ottiene un bonus al potere aggiuntivo del [Arg4]%, fino a un massimo del 1200%."
  },
