  AwakerTalent_141303_TalentDesc_1 = {
    Text = "Questo talento è efficace solo nelle fasi del «Capitolo Astrale».\nCOS, ATT e DIF di questo Risvegliato aumentano del [Arg1]%, e ottiene [Arg2] Keyflare al primo Risveglio.\nIl Danno Fisso inflitto da Pontos agli Affini dell'Estasi aumenta del [Arg3]%.\n\"Caccia Implacabile\" ottiene Danni da tentacolo pari al [Arg4]% dell'ATT per ogni 10 Aliemus consumati. Quando \"Devastazione Gaunt\" infligge Danno, riduce temporaneamente anche la FOR del bersaglio di un valore pari al [Arg5]% della DIF."
  },
