  AwakerTalent_143615_TalentDesc_1 = {
    Text = "Quando questo personaggio è nel team, il Reame del Mare Profondo si trasforma nel Reame \"Benthos: Aequor\".\n\nIl Danno base da tentacolo viene modificato al 5% della Salute massima del team.\n\nAmplificazione del Danno del team +50% dopo l'inizio dell'esplorazione (Effetto raddoppiato se il team è composto interamente da Risvegliatori di Aequor e del Caos, anche se non si otterranno Tentacoli iniziali aggiuntivi).\nL'effetto del Raduno di Tentacoli viene rimosso.\nLa Postura del Tentacolo cambia in \"Benthos: Postura del Tentacolo\".\n\n\"Benthos: Mare Tranquillo\": Genera immediatamente uno Scudo pari al 25% della Salute massima e i Tentacoli non attaccheranno più alla fine del turno; 3 turni di recupero.\n\"Benthos: Onde Furiose\": Danni da tentacolo × 125% per il turno; dopo aver inflitto Danno attivo, 1 Tentacolo attacca; perdi 1 Tentacolo alla fine del turno; 3 turni di recupero.\nLa Padronanza del Reame viene conteggiata come \"Benthos: Padronanza di Aequor\". Ogni punto fornisce: Generazione Scudo della Postura Mare Tranquillo +0,025% della Salute massima. Danni da tentacolo della Postura Onde Furiose +0,025%.\nL'effetto della \"Benthos: Padronanza del Reame\" raddoppia se il team è composto interamente da Risvegliatori di Aequor e del Caos."
  },
  AwakerTalent_143615_TalentName_1 = {
    Text = "Fondale Senza Luce"
  },
