    Text = "·Questo Talento ha effetto solo negli Stadi \"Regno Astrale\".\n·COS, Attacco e DIF di questo Risvegliatore aumentano del [Arg1]%, e dopo che questo Risvegliatore gioca Risveglio per la prima volta, ottiene [Arg2] Keyflare.\n·\"Spada Taglia-Confini\" beneficia di un Bonus di Potere aggiuntivo del [Arg3]%. Dopo aver ucciso un nemico, ottieni [Arg4] Sigilli Neri, che beneficiano del Bonus Bottino di Sigilli di Lotan: Cetarchon. Ha effetto al massimo una volta per battaglia."
  },
