  AwakerTalent_145718_TalentDesc_1 = {
    Text = "Quando Caraboo è nel team, il Reame di Caro muta in Allevamento di carne.\n\nFusione Embrionale: La Fusione Embrionale ottenuta per turno aumenta a 50~100, scalando con la Vita persa. Il limite di Fusione Embrionale aumenta da 100 a 200. Al raggiungimento del limite, aggiungi 1 \"Embrione Propagulo\" in mano.\n\nEmbrione Propagulo: Giocare questa carta non garantisce più il Tasso critico. Divorare non garantisce più Scudo o FOR temporanea. La prima volta che ciascun Risvegliatore consuma un \"Embrione Propagulo\" ogni turno, ottiene 40 accumuli di \"Festa della Propagazione\": Ogni accumulo potenzia i seguenti effetti Finali della prossima Esaltazione di quel Risvegliatore in questo turno dell'1%: Danno Finale, Scudo Fisso, Recupero PV Fisso, FOR Fissa/Riduzione del Potere, Bonus DAN Tentacolo, Veleno Fisso e Contrattacco Fisso.\n\nFornace Cremisi: L'accumulo automatico A inizio turno cambia al 10% della Vita persa, fino al 50% della Salute massima. Non si accumula più alla fine della battaglia. Tempo di recupero di 3 turni.\n\nErosione scarlatta: Dopo aver usato la Fornace Cremisi, infliggi Corrosione a tutti i nemici pari all'1% della loro Salute massima. Più Fornace Cremisi viene consumata, più forte è l'effetto di Corrosione, fino a +100%. Infligge un effetto di Corrosione 5× contro i nemici \"Guscio vuoto\".\n\nAll'inizio dell'esplorazione, Salute massima +10%, Amplificazione del Danno del team +50%, e tutti i Risvegliatori ottengono 20 accumuli di \"Festa della Propagazione\" A inizio turno. Se il team è composto solo da Risvegliatori di Caro o del Caos, l'Amplificazione del Danno concessa da questo effetto raddoppia.\nLa Padronanza del Reame diventa \"Padronanza di Allevamento di carne\": Ogni punto di Padronanza del Reame aumenta gli accumuli di \"Festa della Propagazione\" ottenuti da \"Allevamento di carne\" dello 0,05%.\n\nSe il team è composto solo da Risvegliatori di Caro o del Caos, l'effetto \"Padronanza di Allevamento di carne\" raddoppia."
  },
  AwakerTalent_145718_TalentName_1 = {
    Text = "Allevamento di carne"
  },
  AwakerTalent_146937_TalentDesc_1 = {
    Text = "Quando Lotan: Cetarchon è nel team, il Reame del Caos si rifonde in Primordia: Caos.\n\nAfflusso Primordiale: La Keyflare base è aumentata a 2000, l'Amplificazione del Danno del team è aumentata del 50%, e ATT e DIF di tutti i Risvegliatori sono aumentati del 10%. Se il team è composto esclusivamente da Risvegliatori del Caos, il bonus di Amplificazione del Danno di questo effetto è raddoppiato. All'inizio della battaglia, ottieni 2000 Keyflare.\n\nChiavi Confluenti: I Livelli di Ricarica della chiave d'argento di tutti i Risvegliatori vengono impostati sulla media del team. I Risvegliatori non ottengono più Keyflare dall'Arithmetica consumata; invece, la prima Carta di comando giocata da ciascun Risvegliatore per turno garantisce Keyflare pari a (la loro Ricarica della chiave d'argento × 3) + 100.\n\nRegno Indivisibile: Non attiva più gli effetti Reame Puro, Doppia Padronanza del Reame o Doppia Amplificazione del Danno degli altri Reami.\n\nEco Primordiale: Le Carte di Risveglio ottengono Preparazione 1; la Posse attualmente equipaggiata viene scatenata automaticamente la prima volta che viene giocata ogni turno.\n\nFrammenti di Memoria: La Posse viene sostituita da Primordia: Doppia Ricorrenza e Primordia: Rivelazione della Triade, e la Posse portata non può più essere scatenata.\n\n-Primordia: Doppia Ricorrenza: Scopri 3 Posse tra quelle in mano, poi scegline 1 da scatenare due volte.\n-Primordia: Rivelazione della Triade: Scopri 3 set di Posse tra quelle in mano, ciascun set contenente 3 Posse diverse. Scegli un set per scatenare ogni Posse al suo interno una volta, in sequenza.\nLe Posse presenti in Primordia: Doppia Ricorrenza e Primordia: Rivelazione della Triade sono tratte dagli otto tipi di Memoria Primordiale.\nPrimordia: Doppia Ricorrenza e Primordia: Rivelazione della Triade contano ciascuna come lo scatenamento di 1 sola Posse. Quando i loro effetti si attiverebbero più volte, solo la prima Posse ad avere effetto è valida.\n\nPadronanza del Caos Primordiale: La Padronanza del Reame diventa Padronanza del Caos Primordiale. Ogni punto di Padronanza del Caos Primordiale aumenta la Potenza della Posse dello 0,05%. Ogni punto di Potenza della Posse aumenta Veleno Fisso, Contrattacco Fisso, FOR Fissa, Braci Antiche Fisse del 2%, e Scudo Fisso, Recupero PV Fisso, Riduzione del potere Fissa e guadagno DAN Tentacolo, Tasso critico, Danno critico, Amplificazione del Danno, Padronanza del Reame, Generazione Aliemus, Fusione Embrionale e Generazione Keyflare dell'1%."
  },
  AwakerTalent_146937_TalentName_1 = {
    Text = "Soffio Primordiale"
  },
