  AwakerTalent_44845_TalentDesc_1 = {
    Text = "Per ogni 1% di Resistenza alla Morte che Lily e i suoi AdR e Patto equipaggiati possiedono, lo Scudo Base di \"Palude proibita\" e \"Difesa Base\" aumenta dello 0,25%, e nelle Battaglie Boss, l'accumulo e il limite di Resistenza aumentano dello 0,25%.\nQuando Lily è nella squadra, ottiene 1 carica di Resistenza per ogni HP persi, con un limite di cariche di Resistenza pari ai PV massimi."
