  },
  AwakerTalent_46446_TalentDesc_1 = {
    Text = "Ramona ottiene 2,5 punti aggiuntivi nell'attributo Ricarica della Chiave d'Argento. Ogni livello di Affinità conferisce inoltre a Ramona 0,5 punti nell'attributo Ricarica della Chiave d'Argento.\nPer ogni punto di Livello di Ricarica della Chiave d'Argento, i DAN Base della \"Spada della Regina\" aumentano dell'1% e, dopo l'uso, si ottiene 0,75 di Padronanza del Reame temporanea."
  },
  AwakerTalent_46446_TalentName_1 = {
    Text = "Risonanza di Cuore e Argento"
  },
  AwakerTalent_46487_TalentDesc_1 = {
    Text = "Ramona: Logora ottiene 2,5 punti aggiuntivi di Ricarica della Chiave d'Argento. Ogni livello di Affinità conferisce inoltre a Ramona: Logora 0,5 punti di Ricarica della Chiave d'Argento.\nPer ogni punto di Livello di Ricarica della Chiave d'Argento, l'effetto ciclico di \"Colpo Base\" conferisce a Ramona: Logora lo 0,2% di Tasso Crit., e l'effetto ciclico di \"Difesa Base\" conferisce a Ramona: Logora 0,2 Aliemus."
  },
  AwakerTalent_46487_TalentName_1 = {
    Text = "Risonanza di Cuore e Argento"
  },
  AwakerTalent_49872_TalentDesc_1 = {
    Text = "Per ogni 1 Attributo di Padronanza del Reame posseduto da Nautila, il Danno da Contrattacco di \"Pronti e via\" aumenta dello 0,25%."
  },
  AwakerTalent_49872_TalentName_1 = {
    Text = "Manutenzione Quotidiana"
  },
  AwakerTalent_49873_TalentDesc_1 = {
    Text = "Per ogni 1% di attributo Amplificazione del Danno posseduto da Nymphaea, l'Effetto Veleno Base causato da \"Rintocco di Morte\" e \"Passaggio dell'Ego\" aumenta dello 0,5%."
  },
  AwakerTalent_49873_TalentName_1 = {Text = "Impregnare"},
  AwakerTalent_51744_TalentDesc_1 = {
    Text = [[
All'inizio della battaglia, metti 1 "Ossessione" nella mano.
Il "Colpo Base" di Miryam beneficia del 50% di bonus ai Danni da tentacolo.
Per ogni 1% di Danno critico fornito da Miryam e dalla sua Ruota del destino e Patto equipaggiati, potenzia la Generazione di Potere dell'Esaltazione, i Danni da tentacolo, l'Aliemus e gli effetti di Applicazione/Attivazione del Veleno dello 0,2%.]]
  },
  AwakerTalent_51744_TalentName_1 = {
    Text = "Pietà inestinguibile"
  },
  AwakerTalent_52071_TalentDesc_1 = {
    Text = "Per ogni punto di Livello Ricarica Aliemus che Tulu e le sue AdD e Patto equipaggiati possiedono, \"Colpo\" beneficia di +5% DAN Tentacolo e bonus FOR. \"Ordine dell'Abisso\" riceve il 15% di Potenziamento Danno Tentacolo e DAN FOR."
  },
  AwakerTalent_52071_TalentName_1 = {
    Text = "Potere del Re Divino"
  },
  AwakerTalent_52086_TalentDesc_1 = {
    Text = "Per ogni 1% di Resistenza alla Morte che Sanga e i suoi AdD e Patto equipaggiati possiedono, aumenta l'Aliemus ottenuto da \"Colpo Base\" e \"Difesa Base\" di 0,03 punti, e \"L'arte perduta\" beneficia di un ulteriore 0,15% di Prob. Critico e bonus ai DAN."
  },
  AwakerTalent_52086_TalentName_1 = {
    Text = "Illuminazione della Morte"
  },
  AwakerTalent_54047_TalentDesc_1 = {
    Text = "Per ogni 1 livello dell'attributo Livello Ricarica Aliemus posseduto da Doll, aumenta gli effetti di Recupero PV di \"Chirurgia Esterna\" e \"Scambio Equivalente\" dello 0,5%."
  },
  AwakerTalent_54047_TalentName_1 = {
