  AwakerTalent_54158_TalentDesc_1 = {
    Text = "Per ogni 1% di Tasso Crit. che Sorel e le sue AdO e Patto equipaggiati possiedono, aumenta gli Aliemus ottenuti da \"Difesa Base\" di 0,2."
  },
  AwakerTalent_54158_TalentName_1 = {
    Text = "Guardiano della Vanità"
  },
  AwakerTalent_55109_TalentDesc_1 = {
    Text = "Per ogni 1% di Tasso Critico fornito da Jenkin e dalla sua Ruota del destino e Patto equipaggiati, il DAN Base di \"Colpo Base\" e \"Prendilo! Brown!\" aumenta del 2%."
  },
  AwakerTalent_55109_TalentName_1 = {
    Text = "Un Nemico Comune"
  },
  AwakerTalent_55176_TalentDesc_1 = {
    Text = "Per ogni 1 Livello di Ricarica della Chiave d'Argento fornito da Erica e dalla sua Ruota del destino e Patto equipaggiati, \"Esplosione Elettromagnetica\" conferisce a Erica lo 0,5% di Tasso critico temporaneo e Danno Crit."
  },
  AwakerTalent_55176_TalentName_1 = {
    Text = "Fonte di Energia Esterna"
  },
  AwakerTalent_55202_TalentDesc_1 = {
    Text = [[
All'inizio del turno, ottieni 1 accumulo di Esca Onirica.
Consumare 1 accumulo di Esca Onirica aumenta il Contatore di "Custode degli Smarriti" e "Necropoli dei Sogni" del 5% dell'ATT in questa battaglia.
Per ogni 1% di Amplificazione del Danno fornito da Wanda e dalla sua Ruota del destino e Patto equipaggiati, il Contatore di "Necropoli dei Sogni" aumenta dello 0,75%.]]
  },
  AwakerTalent_55202_TalentName_1 = {
    Text = "Rivelazione"
  },
  AwakerTalent_55367_TalentDesc_1 = {
    Text = "Per ogni 1 punto di Padronanza del Reame fornito da Casiah e dalla sua Ruota del destino e Patto equipaggiati, \"Carnevale Magico\" aumenta tutto il DAN Base di Casiah dello 0,2%."
  },
  AwakerTalent_55367_TalentName_1 = {
    Text = "Maestro di Magia"
  },
  AwakerTalent_55507_TalentDesc_1 = {
    Text = "Per ogni 1% di Bottino di Sigilli fornito da Tinct e dalla sua Ruota del destino e Patto equipaggiati, \"Aurora Stellare\" ottiene un ulteriore 0,15% di Tasso critico temporaneo."
  },
  AwakerTalent_55507_TalentName_1 = {
    Text = "Viaggiatore Planetario"
  },
  AwakerTalent_55837_TalentDesc_1 = {
    Text = "Le Carte di comando \"Attacco\" e \"Difesa\" di Horla sono considerate Salmi.\nQuando le Carte di comando di Horla attivano il loro Effetto Balzo, ella entra nello stato emotivo associato a quel Salmo. Horla può avere un solo stato emotivo attivo alla volta, e attivare l'Effetto Balzo di un Salmo diverso cambierà lo stato emotivo in quello corrispondente. Ogni emozione possiede un potenziamento passivo per tutta la squadra, attivo finché Horla rimane in quello stato emotivo. Ogni stato emotivo potenzia un effetto diverso dell'Esaltazione di Horla. Lo stato emotivo persiste per tutta l'esplorazione.\nPer ogni 1% di Resistenza alla Morte posseduta da Horla, il valore dell'effetto passivo del suo stato emotivo attuale aumenta dello 0,1% del valore originale."
  },
  AwakerTalent_55837_TalentName_1 = {
    Text = "Scrivere con Sentimento"
  },
  AwakerTalent_56174_TalentDesc_1 = {
    Text = "Faros ottiene lo 0,4% di Scudo del Personaggio aggiuntivo da \"Città perduta di Lemuria\" per ogni 1% di Amplificazione del Danno come attributo."
  },
  AwakerTalent_56174_TalentName_1 = {
    Text = "Nostalgia di casa"
  },
  AwakerTalent_56175_TalentDesc_1 = {
    Text = "Per ogni 1% di Bottino di Sigilli posseduto da Caecus, \"Colpo Base\" beneficia di un bonus Contrattacco dell'1%."
  },
  AwakerTalent_56175_TalentName_1 = {
    Text = "Aculei Ribelli"
  },
  AwakerTalent_56223_TalentDesc_1 = {
    Text = "Dopo che Celeste gioca una Carta di comando, attiva 1 Tentacolo per attaccare il nemico. Per ogni punto di Padronanza del Reame posseduto da Celeste, dalle sue AdG e dal Patto, questa attivazione infligge un ulteriore 0,5% di DAN da Tentacolo."
  },
  AwakerTalent_56223_TalentName_1 = {
    Text = "Corno della Navigazione"
  },
  AwakerTalent_57336_TalentDesc_1 = {
    Text = "Per ogni 1% di attributo Bottino di Sigilli posseduto da Salvador, il massimo della Fornace Cremisi aumenta dello 0,15% dei PV Max."
  },
  AwakerTalent_57336_TalentName_1 = {
    Text = "Origine di Ogni Vita"
  },
  AwakerTalent_57408_TalentDesc_1 = {
    Text = "Per ogni 1% di Bottino di Sigilli che Agrippa e i suoi WoD e Patto equipaggiati possiedono, lo Scudo base della \"Benedizione Pallida\" +0,5%, e il Veleno base +1%."
  },
  AwakerTalent_57408_TalentName_1 = {
    Text = "Sigillo del Patto"
  },
  AwakerTalent_57419_TalentDesc_1 = {
    Text = "Per ogni 1% di attributo Resistenza alla Morte posseduto da Faint, il Contatore fornito da \"Culla delle Stelle\" e \"Colore accecante\" aumenta dello 0,2%, e il limite di Resistenza alla Morte di \"Culla delle Stelle\" aumenta del 2%."
  },
  AwakerTalent_57419_TalentName_1 = {
    Text = "Fascia Secondaria"
  },
  AwakerTalent_57567_TalentDesc_1 = {
    Text = "Per ogni 1% di attributo Amplificazione del Danno posseduto da Helot, \"Impasse Sopravvissuta\" aumenta il danno inflitto da Helot in questo turno dello 0,3%."
  },
  AwakerTalent_57567_TalentName_1 = {
    Text = "Sigillo del Dolore"
  },
  AwakerTalent_58448_TalentDesc_1 = {
    Text = "Ryker ottiene 5 Sigilli Neri all'uccisione di un nemico. Per ogni 1% di Bottino di Sigilli che Ryker possiede, la quantità ottenuta +1%, fino a 5 volte per esplorazione.\nDopo aver ottenuto 75/150/300 Sigilli Neri tramite battaglia, capacità reliquie +1, e alla fine della battaglia, scegli un'<C05_zaowu:\"Eredità Caotica\"> da aggiungere alla lista delle reliquie."
  },
  AwakerTalent_58448_TalentName_1 = {
    Text = "Il Vincitore Prende Tutto"
  },
  AwakerTalent_70306_TalentDesc_1 = {
    Text = "Nelle Battaglia Boss, all'inizio del turno e dopo che \"Doll: Inferno\" rilascia Esaltazione, ottieni 1 accumulo di \"Finale\".\"Finale\" può avere un massimo di 10 accumuli, e quando raggiunge 10 accumuli, metti 1 \"Fine dell'Illusione\" nella mano."
  },
  AwakerTalent_70306_TalentName_1 = {
    Text = "Sentiero dell'Annientamento"
  },
  AwakerTalent_74099_TalentDesc_1 = {
    Text = "Questo talento è efficace solo nelle fasi del \"Capitolo Astrale\".\nCOS, ATT e DIF di questo Risvegliato aumentano del [Arg1]%, e ottiene [Arg2] Keyflare al primo Risveglio.\nOgni attacco del Tentacolo aumenta il Danno tentacolo temporaneo del [Arg3]% dell'ATT di Tulu, fino a [Arg4] volte per turno.\nQuando ci sono 1/2/3 altri Risvegliati \"Lemuriani\" nella squadra, tutti i nemici subiscono il 10%/25%/50% in più di Danno Tentacolo."
