  AwakerTalent_74100_TalentDesc_1 = {
    Text = "·Questo Talento è attivo solo negli Stadi del \"Regno Astrale\".\n·COS, ATT e DIF di questo Risvegliatore aumentano del [Arg1]%, e dopo che questo Risvegliatore gioca Risveglio per la prima volta, ottiene [Arg2] punti di Energia-S.\n·L'effetto di Riduzione del potere di \"Faint\" aumenta del [Arg4]%. Dopo aver giocato una Carta di comando \"Faint\", Rubare Temporaneamente il [Arg3]% del Potere dell'ATT di Faint dai nemici \"Umanoide\", con un massimo di 3 attivazioni per turno."
  },
