  AwakerTalent_74101_TalentDesc_1 = {
    Text = "Questo talento è efficace solo nelle fasi \"Astral Reign\".\nCOS, ATT e DIF di questo Risvegliatore +[Arg1]%, e ottiene [Arg2] Keyflare al primo Risveglio.\nRyker ottiene +[Arg3]% Tasso critico e +[Arg4]% Bottino di Sigilli de Il sigillo nero. Se almeno 400 Sigilli Neri sono stati ottenuti in battaglia, potenzia 1 \"Eredità Caotica\" all'inizio della battaglia successiva."
