  AwakerTalent_74110_TalentDesc_1 = {
    Text = "Questo talento è efficace solo nelle fasi del \"Capitolo Astrale\".\nCOS, ATT e DIF di questo Risvegliato aumentano del [Arg1]%, e ottiene [Arg2] Keyflare al primo Risveglio.\nDopo aver giocato \"Intuizione,\" ottieni FOR temporanea pari al [Arg3]% dell'ATT e attiva \"Crescendo\" una volta, fino a un massimo di 5 volte per turno."
