  AwakerTalent_74112_TalentDesc_1 = {
    Text = "·Questo Talento è attivo solo negli Stadi del \"Regno Astrale\".\n·COS, ATT e DIF di questo Risvegliatore aumentano del [Arg1]%, e dopo che questo Risvegliatore gioca Risveglio per la prima volta, ottiene [Arg2] punti di Energia-S.\n·Quando Sanga infligge uno Scudo, ottiene Danni da tentacolo pari al [Arg3]% del valore dello Scudo. Quando Sanga scatena l'Esaltazione, ottiene un Bonus DAN Tentacolo aggiuntivo del [Arg4]%."
  },
