  AwakerTalent_74113_TalentDesc_1 = {
    Text = "Questo talento è efficace solo nelle fasi \"Astral Reign\".\nCOS, ATT e DIF di questo Risvegliatore +[Arg1]%, e ottengono [Arg2] Keyflare al primo Risveglio.\n\"Frusta della Follia\" ottiene Conservare e Preparazione. I nemici con intenzione di attacco subiscono un aumento del [Arg3]% al Danno attivo da Pandia, che aumenta del +5% per ogni istanza di attacco aggiuntiva, fino al 20%."
