  AwakerTalent_74129_TalentDesc_1 = {
    Text = "·Questo Talento è attivo solo negli Stadi del \"Regno Astrale\".\n·COS, ATT e DIF di questo Risvegliatore aumentano del [Arg1]%, e dopo che questo Risvegliatore gioca Risveglio per la prima volta, ottiene [Arg2] punti di Energia-S.\n·Il Danno Finale del \"Colpo\" di Lily aumenta del [Arg3]%, con il valore raddoppiato nella Battaglia Boss. Dopo aver subito un attacco da un nemico \"Ultra\", ottiene un effetto di Guarigione con Ritardo pari al [Arg4]% della Vita persa in quell'attacco. Il \"Colpo di Protezione\" beneficia di un bonus di Amplificazione del Danno del [Arg5]% insieme all'effetto di aumento del Danno di \"Sopportare\"."
  },
