  AwakerTalent_74132_TalentDesc_1 = {
    Text = "·Questo Talento è attivo solo negli Stadi del \"Regno Astrale\".\n·COS, ATT e DIF di questo Risvegliatore aumentano del [Arg1]%, e dopo che questo Risvegliatore gioca Risveglio per la prima volta, ottiene [Arg2] punti di Energia-S.\n·Il Veleno inflitto da Faros aumenta del [Arg3]%. \"La città perduta\" alla fine del turno ordina a tutti i Tentacoli di attaccare 1 volta, ma questi attacchi infliggono solo il [Arg4]% del Danno.\n·Quando nel gruppo sono presenti 1/2/3 altri Risvegliatori \"Lemuria\", Amplificazione del Danno +20%/50%/100%."
  },
