  AwakerTalent_74134_TalentDesc_1 = {
    Text = "Questo talento è efficace solo nelle fasi del \"Capitolo Astrale\".\nCOS, ATT e DIF di questo Risvegliatore aumentano del [Arg1] %, e ottiene [Arg2] Keyflare al primo Risveglio.\nIl Danno Finale di Helot contro i nemici della \"Distesa Innevata\"+[Arg3] %. Se Helot ha consumato un \"Embrione\" in questo turno, il suo prossimo danno inflitto in questo turno ha Danno Crit. +[Arg4] %."
