  AwakerTalent_74137_TalentDesc_1 = {
    Text = "·Questo Talento è attivo solo negli Stadi del \"Regno Astrale\".\n·COS, ATT e DIF di questo Risvegliatore aumentano del [Arg1]%, e dopo che questo Risvegliatore gioca Risveglio per la prima volta, ottiene [Arg2] punti di Energia-S.\n·Quando \"Rovine Cinerea\" si Rigenera, la probabilità che appaia uno sconto aumenta del [Arg3]% e la percentuale di sconto aumenta del [Arg4]%.\n·Il DAN base di \"Decapitazione\" aumenta del [Arg5]%, calcolato indipendentemente dall'aumento del DAN base derivante dall'Uccisione."
  },
