  AwakerTalent_78618_TalentDesc_1 = {
    Text = "Questo talento è efficace solo nelle fasi del \"Capitolo Astrale\".\nCOS, ATT e DIF di questo Risvegliato aumentano del [Arg1] %, e ottiene [Arg2] Keyflare al primo Risveglio.\nIl DAN Base di \"Espiazione nel Dolore\" aumenta del [Arg3] % dell'ATT di Pollux.\nOgni 50 accumuli di \"Marchio del Peccato\", aggiungi 1 \"Sacro Cuore\" alla tua mano.\nQuando il \"Marchio del Peccato\" raggiunge 100 accumuli, pesca 1 Carta abilità di Pollux dopo che \"Sacro Cuore\" viene Esaurito alla 3ª giocata.\nQuando si infliggono danni, l'effetto del \"Marchio del Peccato\"è raddoppiato contro i nemici della \"Chiesa del Portatore di Luce\"."
  },
