  AwakerTalent_78620_TalentDesc_1 = {
    Text = "Questo talento è efficace solo nelle fasi \"Astral Reign\".\nCOS, ATT e DIF di questo Risvegliatore +[Arg1]%, e ottengono [Arg2] Keyflare al primo Risveglio.\nAll'inizio della battaglia, tutti i nemici subiscono il [Arg3]% di Danni da tentacolo in più. Questo effetto raddoppia contro i nemici \"Aequor\". Il Danno attivo inflitto da \"Castigo del Fulmine\" ai nemici \"Aequor\" +[Arg4]%."
  },
