  AwakerTalent_78622_TalentDesc_1 = {
    Text = "Questo talento è efficace solo nelle fasi del \"Capitolo Astrale\".\nCOS, ATT e DIF di questo Risvegliato aumentano del [Arg1]%, e ottiene [Arg2] Keyflare al primo Risveglio.\nEffetti potenziamento di \"Fiamma\" +[Arg3]%. Dopo l'inizio di ogni turno e prima della fase di scarto, rimuovi tutte le \"Bruciature\" dalle carte in mano. Kathigu-Ra ottiene 1 accumulo di \"Combustione\" per ogni accumulo di \"Bruciatura\" rimosso."
