  AwakerTalent_78623_TalentDesc_1 = {
    Text = "Questo talento è efficace solo nelle fasi \"Astral Reign\".\nCOS, ATT e DIF di questo Risvegliatore +[Arg1]%, e ottengono [Arg2] Keyflare al primo Risveglio.\nTasso critico e DAN crit. dell'Esaltazione di Caraboo +[Arg3]%. \"Sazietà\" aumenta la Salute massima del [Arg5]%.\nNel terreno \"Campi di Ghiaccio\": il Costo di Arithmetica di \"Maleficio Nevoso\" -1; il conteggio dei colpi di danno +1; infligge danni & applica Sintomo: Debolezza a tutti i nemici."
