  AwakerTalent_78625_TalentDesc_1 = {
    Text = "Questo talento è efficace solo nei livelli \"Capitolo Astrale\".\nCOS, ATT e DIF di questo Risvegliatore sono aumentati del [Arg1]%, e ottiene [Arg2] Keyflare al primo Risveglio.\n\"Verità, e anche Illusione\" aumenta inoltre il Danno Finale inflitto dall'Esaltazione degli altri Risvegliatori in questo turno del [Arg3]%, e dopo l'uso, l'Aliemus Base di Pickman -5."
