  AwakerTalent_78645_TalentDesc_1 = {
    Text = "Questo Talento è efficace solo nelle fasi del \"Capitolo Astrale\".\nCOS, ATT e DIF di questo Risvegliato aumentano del [Arg1]%, e ottiene [Arg2] Keyflare al primo Risveglio.\nLa Forza ottenuta da tutti i Risvegliati aumenta del [Arg3]%.\nQuando Clementine infligge DAN ai nemici \"Insettoide\", applica un effetto Sanguinamento pari al [Arg4]% del DAN inflitto. La prima volta in ogni round in cui Clementine fornisce uno Scudo del Personaggio o recupera PV, i nemici \"Insettoide\" perdono temporaneamente Forza pari al [Arg5]% della DIF di Clementine."
  },
