    Text = "Questo talento è efficace solo nelle fasi del \"Capitolo Astrale\".\nCOS, ATT e DIF di questo Risvegliato aumentano del [Arg1]%, e ottiene [Arg2] Keyflare al primo Risveglio.\nOgni volta che Murphy: Falsonata infligge Danno, applica al bersaglio cariche di \"Sacrificio\" pari al [Arg3]% del Danno inflitto. L'effetto di aumento delle cariche di \"Rituale di Nascita\" dello stato \"Sigillo Vitale\" è raddoppiato.\nQuando ci sono 1/2/3 altri Risvegliati \"Lemuriani\" nella squadra: PV massimi +6%/15%/30%; si ottiene uno Scudo pari al 50%/125%/250% della DIF di Murphy: Falsonata dopo che un qualsiasi Risvegliato \"Lemuriano\" usa Esaltazione. Limitato a una volta per turno; non beneficia del Bonus Generazione Scudo."
  },
