  AwakerTalent_79211_TalentDesc_1 = {
    Text = [[
La Carta di comando di Clementine ottiene 1 accumulo di "Simbiosi" dopo aver inflitto Danni.
Ogni 1 punto di Rigenerazione Keyflare fornito da Clementine e dalla sua Ruota del destino e Patto equipaggiati aumenta il Tasso Crit. e il Danno Crit. dello 0,35%.
All'inizio del Turno Ultra, rimuovi tutti i "Trauma Psichico" e le "Fissazione fobica" dei nemici. Per ogni accumulo di "Trauma Psichico" rimosso da tutti i nemici, ottieni 50 Keyflare; per ogni accumulo di "Fissazione fobica" rimosso da tutti i nemici, gli altri Risvegliati ottengono 2 Aliemus.]]
  },
