  AwakerTalent_83778_TalentDesc_1 = {
    Text = "Per ogni 1% di Resistenza alla Morte che Corposant e i suoi AdG e Patto equipaggiati possiedono, il suo Danno Base aumenta dello 0,2% e lo Scudo dello 0,05%."
  },
  AwakerTalent_83778_TalentName_1 = {Text = "Braci"},
  AwakerTalent_84132_TalentDesc_1 = {
    Text = "Per ogni 1 Livello Rigenerazione Aliemus in Aurita, all'inizio della battaglia, ottieni l'1% dell'ATT di Aurita come Danni da tentacolo."
  },
  AwakerTalent_84132_TalentName_1 = {
    Text = "Piccola Fata Felice"
  },
  AwakerTalent_89775_TalentDesc_1 = {
    Text = "Giocare \"Piuma d'Onice\" per la prima volta ogni turno infligge l'840% dell'ATT di Castor come \"Corrosione\" al bersaglio e concede 10 Aliemus.\nPer ogni 1% di Amplificazione del Danno che Castor possiede, la quantità base di \"Corrosione\" inflitta +1%.\nDopo la battaglia, la \"Corrosione\" inflitta da Castor +20% permanentemente durante questa Esplorazione.\nLa \"Corrosione\" inflitta nelle Battaglia Boss raddoppia.\nDopo aver inflitto \"Corrosione\", il danno in uscita di Castor +5% della quantità di \"Corrosione\" inflitta in questo turno.\nIl Danno inflitto da Castor non rimuove la \"Corrosione\"."
  },
  AwakerTalent_89775_TalentName_1 = {
    Text = "Piume Purificatrici"
  },
  AwakerTalent_95804_TalentDesc_1 = {
    Text = "Doresain raccoglie 1 «Carcassa» dopo aver ucciso un nemico o aver inflitto DAN Esaltazione a un Boss.\nPuò conservare fino a 3 accumuli di «Carcassa», che vengono mantenuti per tutta l'esplorazione."
  },
